        "id": "sprint-9-t94",
        "title": "1. Provide the correct warranty eligibility period for customer based on purchase date. \n2. Minimize",
        "description": "Enhanching current BOT capabilities for not only to link the device but to also capture the purchase date to DCE 2 / DCX",
        "background": "1. Warranty rule set for P1 devices are based on purchase date and device type of customer :\n- ILUMA 4.0 : 12 Months after purchase date\n- ILUMA 4.1 : 12 Month + 12 Months if it is linked within 30 days from purchase date\n\nIf the purchase date (based on proof of purchase) is not available the warranty eligibility will be refering to production date, the eligibility is : 12 months from production date + 3 months\n\n2. BOT is currently recording new member device link date only, NOT recording the purchase date. \n\n3. The impact is customer will not receive the eligible warranty period and might potentially generate complaints as the warranty periode have been expired during the day of the purchase.",
        "objective": "1. Provide the correct warranty eligibility period for customer based on purchase date. \n2. Minimize potential complaint due to the warranty eligibility period <12 months after purchase date.",
