        "mandays": "67.5",
        "jira": "",
        "dependency": "",
        "description": "Over‑the‑Air (OTA) Update is a mechanism that allows MyHero application updates to be deployed directly from the server to users’ iPad applications, without requiring distribution through the App Store or Company Portal.\n\nThrough OTA, the development team can:\n\n- Deploy updates to JavaScript, business logic, UI/UX, and configuration within minutes\n- Perform silent updates without user interaction\n- Maintain a consistent application version across all active users",
        "background": "The update process for the MyHero application still relies heavily on traditional methods through the Company Portal, which require manual processes, longer waiting times, and user‑initiated actions. This approach often results in inconsistent version adoption across the field, causing delays in distributing bug fixes and new features to all sales users simultaneously.",
        "objective": "- Accelerate application update distribution without dependency on the Company Portal\n- Ensure 100% version consistency across all users\n- Eliminate reliance on manual user actions for application updates\n- Enable rapid bug fixes and business logic updates to minimize disruption to sales activities\n- Improve operational efficiency while reducing manual distribution overhead on the IT side",
        "comments_count": 1,
        "attachments_count": 0,
        "no": "1",
        "ticket_code": "",
        "sub_platform": "My Hero",
        "epic": "Over The Air Update Exploration",
