        "jira": "https://jira.app.pconnect.biz/browse/CDE-65750\nhttps://jira.app.pconnect.biz/browse/CDE-67064\nhttps://jira.app.pconnect.biz/browse/CDE-77272",
        "dependency": "",
        "description": "",
        "background": "CITA currently lacks a proper in-app registration and profile page for unregistered (unreg) retailers. The existing onboarding process is highly fragmented and manual — Pasgar must register unreg retailers via AMO, inject data into the Control Tower using Python scripts, and share one-click links/QR codes externally. Pilot observations in Bandung 2 revealed critical data issues: multiple retailers sharing phone numbers across business IDs, duplicate retailer mappings, and absence of OTP-based ownership validation. Without a native registration flow inside CITA, onboarding scalability is severely limited,",
        "objective": "Build a native profile page and registration page within CITA that enables seamless, field-driven onboarding of unregistered retailers — triggered by Pasgar during store visits — with proper OTP validation, phone number ownership verification, and accurate data mapping to CITA, AYO Principal, and AMO ecosystems; eliminating dependency on external tools and manual data injection",
