        "background": "OSEM has grown from a simple data consumer into a critical operational platform. Its current\nReverse ETL architecture moves data across regions (Ireland → Singapore → OSEM), which — as data volume grows —\ndrives: rising inter-region transfer, replication, and storage costs; higher processing and synchronization latency; high\noperational complexity (incidents require the Application, Data Engineering, and Infrastructure teams to troubleshoot\njointly); and heavy dependency on the Data Engineering team, since every data change must queue in their delivery\nbacklog.​",
