        "objective": "Enable additional, high‑impact use cases on CITA Chat by allowing the system to recognize repeat‑order intent (e.g. last order), in order to reduce ordering friction, improve chat adoption, and validate conversational behavior ahead of the future AI/LLM implementation.",
