        "priority": "Medium",
        "stage": "todo",
        "progress": 0,
        "mandays": "28.5",
        "jira": "",
        "dependency": "No PRD shared to ITPD",
        "description": "adding Optional and Mandatory setting for myHero new release update by territory, this required when deploying new realase on limited territory or area only",
        "background": "The current deployment mechanism for MyHero application releases applies updates uniformly across all territories without the capability to control rollout scope. This limitation creates operational constraints when implementing incremental releases, pilot testing, or phased rollouts in selected regions. As a result, any new release must be deployed nationally, increasing the risk of widespread impact in case of defects, configuration issues, or unforeseen performance challenges.\nTo support more controlled and flexible deployment strategies, there is a need to introduce configurable settings that allow distinguishing between mandatory and optional updates at a territory level",
        "objective": "To enhance the MyHero release management capability by introducing a configurable setting that enables:\nTerritory-based deployment control, allowing new releases to be applied selectively to specific regions or areas.\nUpdate classification (Mandatory vs. Optional):\n\nMandatory: Enforces users within selected territories to adopt the new release.\nOptional: Allows users to update at their discretion within selected territories.",
