        "jira": "",
        "dependency": "No PRD shared to ITPD",
        "description": "Faster process of information cascading to SRCC on RFT issues which leads to faster follow-up by retailers",
        "background": "Currently, there are recurring issues where RFT transactions failed to be transferred to SRC due to bank account problems, such as mismatched names (owner name differs from the registered name) and duplicated bank account number across SRC owners. \nThe issue results in delays beyond the standardized SLA, with SRC receiving the coins after >14 working days. Additionally, SRC may not be aware that the problem originates from their bank account details.\nHQ has regularly shared RFT status reports to Zone, but it usually takes time for the information to be cascaded to area level. Hence, resulted in lengthy SLA.\nOut of 1.5K weekly interactions ± 20 – 30% are related to coin issue, while agents lack detailed visibility within the AYO Principle Backend system which issue caused the delay",
        "objective": "Accelerate cascade of information to solve “invalid” bank account issues in more timely manner\nMinimize complaint escalation to CSC & related department due to “unclear” reason of lengthy process of RFT\nClarity of information on RFT issue, both for retailer & SRCC as direct point of contact to retailer",
