        "mandays": "146.81",
        "jira": "",
        "dependency": "",
        "description": "QRIS will be introduced as an additional payment method within the MyHero Taking Order process. Once selected by the salesman, the system will generate and display a QRIS code based on the transaction amount for the customer to complete the payment. The payment status will be updated based on the payment vendor’s response, while the transaction data will be processed through MyHero Backend for settlement and disbursement.\n\nThe solution will also include real-time QRIS status checking, payment-status recording, detailed cashless transaction information in the Settlement Report, and payment disbursement to the respective entities. A single QRIS payment can support a transaction involving multiple entities, with the payment allocation and disbursement managed through the backend. QRIS will serve as an additional payment option and will not replace hard cash.",
        "background": "The current payment and collection process is still largely dependent on hard cash, requiring manual activities from cash collection and deposit through settlement. To provide customers with a more convenient payment alternative and improve Field Force operational efficiency, QRIS will be introduced as a cashless payment option within the MyHero Taking Order process, without replacing the existing cash payment method.",
        "objective": "- Provide customers with a convenient and flexible cashless payment option.\n- Reduce dependency on cash and eliminate the need for customers to prepare an exact payment amount.\n- Streamline the collection, settlement, and disbursement processes across entities.\n- Improve Field Force productivity through a more efficient payment and settlement process.\n- Enhance transaction transparency and traceability through payment-status monitoring and detailed settlement reporting.",
